(() => {
  'use strict';
  const VERSION = '__APP_VERSION__';
  const DB_NAME = 'thirty-days-of';
  const STORE = 'app';
  const $ = (s, root=document) => root.querySelector(s);
  const esc = (s='') => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const localISO = (d=new Date()) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const parseDate = s => {const [y,m,d]=String(s).split('-').map(Number);return new Date(y,m-1,d,12)};
  const shiftDate = (s,n) => {const d=parseDate(s);d.setDate(d.getDate()+n);return localISO(d)};
  const dateDiff = (a,b) => Math.round((parseDate(b)-parseDate(a))/86400000);
  const fmtDate = s => s ? parseDate(s).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}) : '—';
  const id = () => crypto.randomUUID ? crypto.randomUUID() : 'id-'+Date.now().toString(36)+Math.random().toString(36).slice(2);
  let data = {challenges:[],settings:{theme:'system',notifications:false,dailyReminder:false,dailyTime:'07:00',incompleteReminder:false,incompleteTime:'20:00'}};
  let currentFilter='active', searchTerm='', deferredInstall=null, undoAction=null, toastTimer=null, db=null;
  const main=$('#main'), modalRoot=$('#modalRoot'), toast=$('#toast');

  function openDB(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window)){reject(Error('IndexedDB unavailable'));return}const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>req.result.createObjectStore(STORE);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
  async function load(){try{db=await openDB();const t=db.transaction(STORE,'readonly');const req=t.objectStore(STORE).get('state');const saved=await new Promise((res,rej)=>{req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)});if(saved)data=normalize(saved)}catch(e){try{const s=JSON.parse(localStorage.getItem(DB_NAME)||'null');if(s)data=normalize(s)}catch{};toastMsg('Using browser fallback storage on this device.')}applyTheme()}
  function normalize(x){return {challenges:Array.isArray(x?.challenges)?x.challenges.map(c=>({...c,days:Array.isArray(c.days)?c.days:[],weeklyGoals:c.weeklyGoals||{week1:'',week2:'',week3:'',week4:''},measurement:c.measurement||{enabled:false,unit:''},status:['active','paused','completed','archived'].includes(c.status)?c.status:'active',awards:Array.isArray(c.awards)?c.awards:[],awardLog:Array.isArray(c.awardLog)?c.awardLog:[]})):[],settings:{...data.settings,...(x?.settings||{})}}}
  async function save(){try{if(db){const t=db.transaction(STORE,'readwrite');t.objectStore(STORE).put(data,'state');await new Promise((res,rej)=>{t.oncomplete=res;t.onerror=()=>rej(t.error)})}else localStorage.setItem(DB_NAME,JSON.stringify(data))}catch(e){toastMsg('Could not save your data. Free up browser storage and try again.');console.error(e)}}
  function toastMsg(message,undo,action){clearTimeout(toastTimer);toast.innerHTML=`<span>${esc(message)}</span>${undo?'<button id="undoBtn">Undo</button>':''}${action?`<button id="toastActionBtn">${esc(action.label)}</button>`:''}`;toast.classList.add('show');if(undo)$('#undoBtn').onclick=()=>{undo();hideToast()};if(action)$('#toastActionBtn').onclick=()=>{hideToast();action.onClick()};toastTimer=setTimeout(hideToast,action?9000:5000)}
  function hideToast(){toast.classList.remove('show')}
  function applyTheme(){const t=data.settings.theme;const dark=t==='dark'||(t==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.body.classList.toggle('dark',dark)}
  matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(data.settings.theme==='system')applyTheme()});
  function challengeDates(c){const start=shiftDate(c.startDate,1-c.startingDay);return Array.from({length:30},(_,i)=>shiftDate(start,i))}
  function currentDay(c){return Math.max(1,Math.min(30,c.startingDay+dateDiff(c.startDate,localISO())))}
  function goalFor(c,day){const w=day<=7?'week1':day<=14?'week2':day<=21?'week3':'week4';return c.weeklyGoals?.[w]||''}
  function dayRecord(c,day){return c.days.find(x=>Number(x.day)===day)||null}
  function dayState(c,day){const rec=dayRecord(c,day), date=challengeDates(c)[day-1], today=localISO();if(rec?.completed)return 'completed';if(rec?.skipped)return 'skipped';if(date===today)return 'today';if(date<today&&day>=c.startingDay)return 'missed';if(day<c.startingDay&&!rec)return 'unrecorded';return 'upcoming'}
  function completedCount(c){return c.days.filter(d=>d.completed).length}
  function missedCount(c){return Array.from({length:30},(_,i)=>dayState(c,i+1)).filter(x=>x==='missed').length}
  function remainingCount(c){let count=0;for(let d=Math.max(1,c.startingDay);d<=30;d++){const s=dayState(c,d);if(s!=='completed'&&s!=='missed')count++}return count}
  function streak(c){const through=Math.max(1,currentDay(c));const completed=new Set(c.days.filter(d=>d.completed).map(d=>Number(d.day)));let best=0,run=0;for(let d=1;d<=through;d++){if(completed.has(d)){run++;best=Math.max(best,run)}else run=0}let anchor=through;if(challengeDates(c)[through-1]===localISO()&&!completed.has(through))anchor--;let now=0;for(let d=anchor;d>=1&&completed.has(d);d--)now++;return {current:now,longest:Math.max(best,now)}}
  function rate(c){const done=completedCount(c),eligible=done+missedCount(c);return eligible?Math.round(done/eligible*100):0}
  function progress(c){return Math.round(completedCount(c)/30*100)}
  function awardDefs(){return [
    ['getting-started','🌱','Getting Started','Complete Day 1.',c=>completedCount(c)>=1],
    ['three-in-a-row','⚡','Three in a Row','Complete 3 consecutive days.',c=>streak(c).longest>=3],
    ['one-week-strong','🌿','One Week Strong','Complete 7 consecutive days.',c=>streak(c).longest>=7],
    ['double-digits','🔟','Double Digits','Reach Day 10.',c=>currentDay(c)>=10],
    ['halfway','🌗','Halfway There','Reach Day 15.',c=>currentDay(c)>=15],
    ['three-weeks','🌳','Three Weeks Strong','Complete 21 days.',c=>streak(c).longest>=21],
    ['final-stretch','🏁','Final Stretch','Reach Day 25.',c=>currentDay(c)>=25],
    ['perfect-week','✨','Perfect Week','Complete all days in any seven-day stretch.',c=>{let s=Array.from({length:30},(_,i)=>dayRecord(c,i+1)?.completed);return s.some((_,i)=>i<=23&&s.slice(i,i+7).every(Boolean))}],
    ['unstoppable','🔥','Unstoppable','Reach a 14-day streak.',c=>streak(c).longest>=14],
    ['challenge-complete','🎉','Challenge Complete','Complete all 30 days.',c=>completedCount(c)>=30],
    ['perfect-30','💎','Perfect 30','Complete all 30 days without a missed day.',c=>completedCount(c)>=30&&missedCount(c)===0]
  ]}
  function refreshAwards(c,day=currentDay(c)){const earned=[];const defs=awardDefs();c.awardLog=Array.isArray(c.awardLog)?c.awardLog:[];for(const [key,icon,name,desc,cond] of defs){if(cond(c)&&!c.awards.includes(key)){c.awards.push(key);c.awardLog.push({id:key,day,date:challengeDates(c)[day-1]});earned.push({id:key,icon,name})}}return earned}
  function streakAt(c,day){const completed=new Set(c.days.filter(x=>x.completed&&Number(x.day)<=day).map(x=>Number(x.day)));let longest=0,run=0;for(let n=1;n<=day;n++){if(completed.has(n)){run++;longest=Math.max(longest,run)}else run=0}let current=0;for(let n=day;n>=1&&completed.has(n);n--)current++;return {current,longest}}
  function awardNames(c,ids){return ids.map(key=>{const d=awardDefs().find(x=>x[0]===key);return d?`${d[1]} ${d[2]}`:key}).join(', ')}
  function dayGraphicPrompt(c,day){const rec=dayRecord(c,day)||{},date=challengeDates(c)[day-1],st=streakAt(c,day),awards=(c.awardLog||[]).filter(a=>Number(a.day)===day).map(a=>a.id),completion=Math.round(completedCount({days:c.days.filter(x=>Number(x.day)<=day)})/30*100);const result=c.measurement?.enabled&&rec.value!==null&&rec.value!==''?`Measured result: ${rec.value} ${c.measurement.unit}.`:'';return `Create a polished square social graphic, exactly 1:1 aspect ratio (1024 × 1024), celebrating a completed day in the “30 Days of…” app.\n\nChallenge: ${c.title}\nDescription: ${c.description||'A personal 30-day challenge.'}\nDay completed: ${day} of 30\nGoal for today: ${goalFor(c,day)||'Showed up for the challenge'}\nCompletion date: ${fmtDate(date)}\nProgress at this point: ${completedCount({days:c.days.filter(x=>Number(x.day)<=day)})} of 30 days (${completion}%)\nCurrent streak: ${st.current} ${st.current===1?'day':'days'}\nLongest streak so far: ${st.longest} ${st.longest===1?'day':'days'}${result?'\n'+result:''}\nAwards earned today: ${awards.length?awardNames(c,awards):'No new award today.'}\n\nArt direction: use the exact app name “30 Days of…” as clear, readable branding; create an uplifting, expressive visual that reflects this specific challenge rather than generic fitness imagery. Use a soft sky gradient, airy translucent glass panels, teal and coral accents with touches of lilac, deep navy text, and a refined modern mobile-app aesthetic. Make the day number, completed goal, streak, and any award immediately readable. Include a bold checkmark or progress ring and small celebratory details. Keep all text inside generous safe margins. Do not invent extra statistics, awards, logos, or text. Do not include personal journal notes.`}
  function completionGraphicPrompt(c){const st=streak(c),vals=c.days.filter(x=>x.completed&&x.value!==null&&x.value!==''&&Number.isFinite(Number(x.value))).map(x=>Number(x.value)),sum=vals.reduce((a,b)=>a+b,0),ids=c.awards||[];return `Create a polished square social graphic, exactly 1:1 aspect ratio (1024 × 1024), celebrating completion of a full 30-day challenge in the “30 Days of…” app.\n\nChallenge: ${c.title}\nDescription: ${c.description||'A personal 30-day challenge.'}\nMilestone: 30 of 30 days complete — 100%\nChallenge dates: ${fmtDate(challengeDates(c)[0])} to ${fmtDate(c.finishedAt||challengeDates(c)[29])}\nCurrent streak: ${st.current} ${st.current===1?'day':'days'}\nLongest streak: ${st.longest} ${st.longest===1?'day':'days'}\nMissed days: ${missedCount(c)}${c.measurement?.enabled&&vals.length?`\nTotal recorded: ${sum} ${c.measurement.unit}\nAverage per completed day: ${(sum/vals.length).toFixed(1)} ${c.measurement.unit}`:''}\nAwards earned: ${ids.length?awardNames(c,ids):'None recorded'}\n\nArt direction: use the exact app name “30 Days of…” as clear, readable branding; create an expressive, premium-feeling celebration inspired by a fresh start and sustained effort. Use a soft sky gradient, airy translucent glass panels, teal and coral accents with touches of lilac, deep navy text, and a refined modern mobile-app aesthetic. Make “30/30”, “100% complete”, the challenge title, longest streak, and earned awards easy to read. Include a celebratory progress ring or checkmark, subtle confetti, and generous safe margins. Do not invent extra statistics, awards, logos, or text. Do not include personal journal notes.`}
  async function copyGraphicPrompt(prompt,label='Prompt copied. Paste it into ChatGPT.'){try{await navigator.clipboard.writeText(prompt);toastMsg(label)}catch{modal('Copy your graphic prompt','Clipboard access is unavailable here. Select and copy the prompt below.',`<div class="field"><textarea class="graphic-prompt" id="graphicPromptText" readonly>${esc(prompt)}</textarea></div>`,`<button class="button button-quiet" data-close>Close</button><button class="button" id="retryPromptCopy">Copy prompt</button>`,true);const field=$('#graphicPromptText');field?.focus();field?.select();$('#retryPromptCopy').onclick=async()=>{try{await navigator.clipboard.writeText(prompt);closeModal();toastMsg(label)}catch{field?.focus();field?.select();toastMsg('Prompt selected. Copy it and paste it into ChatGPT.')}}}}
  function updateCompletion(c){if(completedCount(c)>=30){c.status='completed';c.finishedAt=challengeDates(c)[29]}else if(c.status==='completed'){c.status='active';c.finishedAt=null}else if(c.status==='archived'&&c.previousStatus==='completed'){c.previousStatus='active';c.finishedAt=null}c.updatedAt=new Date().toISOString()}
  function todayNeeds(){return data.challenges.filter(c=>c.status==='active'&&challengeDates(c)[currentDay(c)-1]===localISO()&&!dayRecord(c,currentDay(c))?.completed&&!dayRecord(c,currentDay(c))?.skipped)}
  function summary(){const active=data.challenges.filter(c=>c.status==='active');return {active:active.length,done:active.filter(c=>dayRecord(c,currentDay(c))?.completed).length,best:Math.max(0,...active.map(c=>streak(c).current)),completed:data.challenges.filter(c=>c.status==='completed').length}}
  function challengeCard(c){const day=currentDay(c),st=streak(c),todayDone=!!dayRecord(c,day)?.completed,status=dayState(c,day),goal=goalFor(c,day);return `<article class="challenge-card"><div class="card-top"><div><a href="#challenge/${encodeURIComponent(c.id)}"><h3>${esc(c.title)}</h3></a>${c.description?`<p class="card-desc">${esc(c.description)}</p>`:''}</div><span class="chip ${status==='today'?'today-chip':''}">${c.status==='paused'?'Paused':status==='completed'?'Complete':todayDone?'✓ Today done':'Day '+day}</span></div><div class="card-progress-row"><span class="day-label">Day ${day} <span class="muted">of 30</span></span><span class="percent-label">${progress(c)}%</span></div><div class="progress-track" role="progressbar" aria-label="${esc(c.title)} progress" aria-valuenow="${progress(c)}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${progress(c)}%"></div></div><div class="card-stats"><span><strong class="streak">🔥 ${st.current}</strong> day streak</span><span><strong>${completedCount(c)}</strong> done</span><span><strong>${missedCount(c)}</strong> missed</span></div>${goal?`<div class="goal-box"><span>Today's goal</span>${esc(goal)}</div>`:''}<div class="card-actions">${c.status==='active'?`<button class="button ${todayDone?'button-quiet':''}" data-action="${todayDone?'edit-today':'complete-today'}" data-id="${esc(c.id)}">${todayDone?'Edit today':'Complete today'}</button>`:''}<a class="button button-quiet" href="#challenge/${encodeURIComponent(c.id)}">View details</a></div></article>`}
  function noChallenges(){return `<section class="empty-state"><img class="empty-mark" src="./assets/logo.svg" alt=""><p class="eyebrow">Small steps, every day</p><h2>What will you do for the next 30 days?</h2><p>Pick something meaningful. Show up one day at a time. Your progress stays on this device.</p><button class="button" data-action="new">Start a challenge</button><div class="example-pills"><button data-example="Push-ups">Push-ups</button><button data-example="Guitar">Guitar</button><button data-example="Reading">Reading</button><button data-example="Meditation">Meditation</button></div></section>`}
  function renderToday(){const active=data.challenges.filter(c=>c.status==='active');const s=summary();return `<div class="page-heading"><div><p class="eyebrow">${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</p><h1>Today</h1><p class="subtitle">A little progress adds up.</p></div><button class="button" data-action="new">＋ New challenge</button></div>${!data.challenges.length?noChallenges():`<div class="summary-grid"><div class="summary-card"><div class="summary-label">Active challenges</div><div class="summary-value">${s.active}</div></div><div class="summary-card"><div class="summary-label">Completed today</div><div class="summary-value">${s.done}<span class="muted" style="font-size:16px"> / ${s.active}</span></div></div><div class="summary-card"><div class="summary-label">Best current streak</div><div class="summary-value">${s.best} <span class="muted" style="font-size:15px">${s.best===1?'day':'days'}</span></div></div><div class="summary-card"><div class="summary-label">Challenges completed</div><div class="summary-value">${s.completed}</div></div></div>${active.length?`<div class="section-heading"><h2>Your challenges</h2><a class="text-button" href="#challenges">See all →</a></div><div class="challenge-grid">${active.map(challengeCard).join('')}</div>`:`<section class="empty-state"><img class="empty-mark" src="./assets/logo.svg" alt=""><h2>No active challenges</h2><p>Start one, or resume a paused challenge when you're ready.</p><button class="button" data-action="new">Start a challenge</button></section>`}`}`}
  function renderChallenges(){const statuses=['active','completed','paused','archived','all'];let list=data.challenges.filter(c=>currentFilter==='all'||c.status===currentFilter);if(searchTerm){const q=searchTerm.toLowerCase();list=list.filter(c=>`${c.title} ${c.description} ${c.days.map(x=>x.notes||'').join(' ')}`.toLowerCase().includes(q))}return `<div class="page-heading"><div><p class="eyebrow">Your journey</p><h1>Challenges</h1><p class="subtitle">One good day at a time.</p></div><button class="button" data-action="new">＋ New challenge</button></div><div class="list-header"><div class="filter-row">${statuses.map(x=>`<button class="filter-pill ${currentFilter===x?'active':''}" data-filter="${x}">${x==='all'?'All':x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><input class="search-input" id="search" aria-label="Search challenges and notes" placeholder="Search challenges or notes" value="${esc(searchTerm)}"></div>${list.length?`<div class="challenge-grid">${list.map(challengeCard).join('')}</div>`:`<div class="empty-state"><h2>No ${currentFilter==='all'?'matching':currentFilter} challenges</h2><p>${searchTerm?'Try another search.':'Start a challenge and it will appear here.'}</p>${currentFilter==='active'?'<button class="button" data-action="new">Start a challenge</button>':''}</div>`}`}
  function renderTodayView(){const list=todayNeeds();const done=data.challenges.filter(c=>c.status==='active'&&dayRecord(c,currentDay(c))?.completed);const active=data.challenges.filter(c=>c.status==='active');const s=summary();return `<div class="page-heading"><div><p class="eyebrow">${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</p><h1>Today</h1><p class="subtitle">A little progress adds up.</p></div><button class="button" data-action="new">＋ New challenge</button></div>${!data.challenges.length?noChallenges():`<div class="summary-grid"><div class="summary-card"><div class="summary-label">Active challenges</div><div class="summary-value">${s.active}</div></div><div class="summary-card"><div class="summary-label">Completed today</div><div class="summary-value">${s.done}<span class="muted" style="font-size:16px"> / ${s.active}</span></div></div><div class="summary-card"><div class="summary-label">Best current streak</div><div class="summary-value">${s.best} <span class="muted" style="font-size:15px">${s.best===1?'day':'days'}</span></div></div><div class="summary-card"><div class="summary-label">Challenges completed</div><div class="summary-value">${s.completed}</div></div></div>${active.length?`<div class="section-heading"><h2>Your challenges</h2><a class="text-button" href="#challenges">See all →</a></div><div class="challenge-grid">${active.map(challengeCard).join('')}</div>`:`<div class="empty-state"><h2>No active challenges</h2><p>Start one, or resume a paused challenge when you're ready.</p><button class="button" data-action="new">Start a challenge</button></div>`}`}<div class="section-heading"><h2>Today's challenges</h2><span class="chip">${list.length?`${list.length} to go`:'All done'}</span></div>${list.length?`<div class="today-list">${list.map(c=>`<article class="today-row"><div><div class="today-name">${esc(c.title)}</div><div class="today-meta">Day ${currentDay(c)} of 30${goalFor(c,currentDay(c))?' · '+esc(goalFor(c,currentDay(c))):''}</div></div><div class="today-tools"><button class="text-button" data-action="daily" data-id="${esc(c.id)}">Notes</button><button class="button done-button" data-action="complete-today" data-id="${esc(c.id)}">Complete</button></div></article>`).join('')}</div>`:''}${done.length?`<div class="section-heading"><h2>Completed today</h2></div><div class="today-list">${done.map(c=>`<article class="today-row"><div><div class="today-name">✓ ${esc(c.title)}</div><div class="today-meta">Day ${currentDay(c)} · ${esc(goalFor(c,currentDay(c))||'Done for today')}</div></div><div class="today-tools"><button class="text-button" data-action="daily" data-id="${esc(c.id)}">Edit notes</button><button class="text-button" data-action="copy-day-prompt" data-id="${esc(c.id)}" data-day="${currentDay(c)}">Copy graphic prompt</button><button class="button button-quiet done-button" data-action="edit-today" data-id="${esc(c.id)}">Completed</button></div></article>`).join('')}</div>`:''}${!list.length&&!done.length&&active.length?`<div class="notice">You have no challenge actions scheduled for today. Your progress is still right where you left it.</div>`:''}`}

  function awardStatus(){const all=[];for(const c of data.challenges){for(const a of c.awards){const d=awardDefs().find(x=>x[0]===a);if(d)all.push({id:a,icon:d[1],name:d[2],desc:d[3],challenge:c.title,date:c.updatedAt})}}return all}
  function renderAwards(){const earned=awardStatus();return `<div class="page-heading"><div><p class="eyebrow">Recognize your consistency</p><h1>Awards</h1><p class="subtitle">${earned.length} earned across ${data.challenges.length} ${data.challenges.length===1?'challenge':'challenges'}.</p></div></div><div class="award-grid">${awardDefs().map(([key,icon,name,desc,cond])=>{const owners=data.challenges.filter(cond);return `<article class="award-card ${owners.length?'':'locked'}"><div class="award-icon">${icon}</div><div><h3>${name}</h3><p>${desc}</p>${owners.length?`<div class="award-check">Earned · ${esc(owners.map(c=>c.title).join(', '))}</div>`:`<div class="award-check muted">Still ahead</div>`}</div></article>`}).join('')}</div>`}
  function renderHistory(){const list=data.challenges.filter(c=>['completed','archived'].includes(c.status));return `<div class="page-heading"><div><p class="eyebrow">Look how far you've come</p><h1>History</h1><p class="subtitle">Completed and archived challenges stay here.</p></div></div>${list.length?list.map(c=>`<article class="history-item"><div><h3>${esc(c.title)}</h3><p>${c.status==='completed'?'Completed':'Archived'} · ${fmtDate(c.startDate)} – ${fmtDate(c.finishedAt||challengeDates(c)[currentDay(c)-1])} · ${completedCount(c)}/30 days · ${rate(c)}% completion</p></div><div class="button-row"><button class="button button-quiet" data-action="duplicate" data-id="${esc(c.id)}">Do it again</button><a class="button button-quiet" href="#challenge/${encodeURIComponent(c.id)}">Details</a></div></article>`).join(''):`<div class="empty-state"><h2>Your story starts today</h2><p>Completed and archived challenges will be saved here.</p><a class="button" href="#challenges">View challenges</a></div>`}`}
  function renderSettings(){const s=data.settings;return `<div class="page-heading"><div><p class="eyebrow">Make it yours</p><h1>Settings</h1><p class="subtitle">Preferences and local data controls.</p></div></div><div class="settings-layout"><section class="settings-card"><h2>Notifications</h2><div class="setting-row"><div><div class="setting-label">Notifications</div><div class="setting-help">Opt in to reminders. Your browser may ask for permission.</div></div><input class="switch" type="checkbox" data-setting="notifications" ${s.notifications?'checked':''} aria-label="Enable notifications"></div><div class="setting-row"><div><div class="setting-label">Daily challenge reminder</div><div class="setting-help">A morning reminder for today's challenges.</div></div><input class="switch" type="checkbox" data-setting="dailyReminder" ${s.dailyReminder?'checked':''} aria-label="Daily challenge reminder" ${s.notifications?'':'disabled'}></div><div class="setting-row"><div class="setting-label">Reminder time</div><div class="setting-control"><input type="time" data-setting="dailyTime" value="${esc(s.dailyTime)}" ${s.notifications&&s.dailyReminder?'':'disabled'} aria-label="Daily reminder time"></div></div><div class="setting-row"><div><div class="setting-label">Incomplete day reminder</div><div class="setting-help">A nudge if challenges are still waiting.</div></div><input class="switch" type="checkbox" data-setting="incompleteReminder" ${s.incompleteReminder?'checked':''} aria-label="Incomplete day reminder" ${s.notifications?'':'disabled'}></div><div class="setting-row"><div class="setting-label">Incomplete reminder time</div><div class="setting-control"><input type="time" data-setting="incompleteTime" value="${esc(s.incompleteTime)}" ${s.notifications&&s.incompleteReminder?'':'disabled'} aria-label="Incomplete reminder time"></div></div><p class="notice">Web notifications need permission and work best while the app is open. Browsers do not reliably schedule reminders while a static PWA is fully closed; reminders are checked when you open or return to the app.</p><button class="button button-quiet" data-action="permission">Check notification permission</button></section><section class="settings-card"><h2>Appearance</h2><div class="setting-row"><div><div class="setting-label">Theme</div><div class="setting-help">Choose a look that feels comfortable.</div></div><div class="setting-control"><select data-setting="theme" aria-label="Appearance theme"><option value="system" ${s.theme==='system'?'selected':''}>System</option><option value="light" ${s.theme==='light'?'selected':''}>Light</option><option value="dark" ${s.theme==='dark'?'selected':''}>Dark</option></select></div></div></section><section class="settings-card"><h2>Data</h2><p class="setting-help" style="margin-bottom:14px">Your challenges stay on this device. Keep a backup somewhere safe.</p><div class="button-row"><button class="button button-quiet" data-action="export">Export backup</button><button class="button button-quiet" data-action="import">Import backup</button></div><div class="divider"></div><button class="button button-danger" data-action="reset">Reset app data</button></section><section class="settings-card"><h2>Application</h2><div class="about-flex"><img class="about-logo" src="./assets/logo.svg" alt=""><div><div class="setting-label">30 Days of…</div><div class="setting-help">Version ${VERSION} · Your pace, your progress.</div></div></div><div class="divider"></div><div class="setting-row"><div><div class="setting-label">Install this app</div><div class="setting-help">Add it to your home screen for quick access and offline use.</div></div><button class="button button-quiet" data-action="install">How?</button></div><div class="setting-row"><div><div class="setting-label">App updates</div><div class="setting-help">Updates install automatically when available.</div></div><span class="chip">${'serviceWorker' in navigator?'Ready':'Browser mode'}</span></div></section></div>`}
  function weeklyPercent(c,w){const from=w*7+1,to=Math.min(30,from+6);let done=0,total=0;for(let d=from;d<=to;d++){const s=dayState(c,d);if(s==='completed'||s==='missed'){total++;if(s==='completed')done++}}return total?Math.round(done/total*100):0}
  function renderDetail(c){const day=currentDay(c),ds=challengeDates(c),st=streak(c),vals=c.days.filter(x=>x.completed&&x.value!==null&&x.value!==''&&Number.isFinite(Number(x.value))).map(x=>Number(x.value)),avg=vals.length?(vals.reduce((a,b)=>a+b,0)/vals.length).toFixed(1):'—',high=vals.length?Math.max(...vals):'—',low=vals.length?Math.min(...vals):'—';const ring=2*Math.PI*67,offset=ring-(ring*progress(c)/100);return `<div class="detail-head"><div><p class="eyebrow">${c.status==='active'?'Your current challenge':c.status[0].toUpperCase()+c.status.slice(1)}</p><h1>${esc(c.title)}</h1><p class="subtitle">${esc(c.description||'A personal 30-day challenge.')}</p></div><div class="detail-actions"><button class="button button-quiet" data-action="edit-challenge" data-id="${esc(c.id)}">Edit</button><button class="button button-quiet" data-action="status" data-id="${esc(c.id)}">${c.status==='paused'?'Resume':c.status==='active'?'Pause':c.status==='archived'?'Restore':'Archive'}</button><button class="button button-quiet" data-action="delete" data-id="${esc(c.id)}">•••</button></div></div><section class="detail-overview"><div><p class="eyebrow">${c.status==='completed'?'A wonderful finish':'Keep showing up'}</p><h2>Day ${day} <span class="muted">of 30</span></h2><div class="big-progress">${progress(c)}<span style="font-size:20px">%</span></div><p class="muted">${completedCount(c)} ${completedCount(c)===1?'day':'days'} complete · ${remainingCount(c)} remaining</p><p class="muted">${fmtDate(ds[0])} – ${fmtDate(ds[29])}</p></div><div class="detail-progress"><svg viewBox="0 0 150 150" aria-hidden="true"><circle cx="75" cy="75" r="67"/><circle class="ring" cx="75" cy="75" r="67" stroke-dasharray="${ring}" stroke-dashoffset="${offset}"/></svg><span>${completedCount(c)}<small style="font:500 13px DM Sans"> / 30</small></span></div></section><div class="detail-stats"><div class="detail-stat"><b>${st.current} 🔥</b><span>Current streak</span></div><div class="detail-stat"><b>${Math.max(st.longest,st.current)}</b><span>Longest streak</span></div><div class="detail-stat"><b>${missedCount(c)}</b><span>Missed days</span></div><div class="detail-stat"><b>${rate(c)}%</b><span>Completion rate</span></div></div><div class="section-heading"><h2>30-day calendar</h2><span class="chip">Tap a day to edit</span></div><div class="calendar" role="grid" aria-label="Challenge day calendar">${ds.map((date,i)=>{const d=i+1,state=dayState(c,d),symbol=state==='completed'?'✓':state==='missed'?'·':state==='today'?'•':state==='upcoming'?'–':state==='skipped'?'↷':'○';return `<button class="day-tile ${state}" data-action="daily" data-id="${esc(c.id)}" data-day="${d}" aria-label="Day ${d}, ${state}, ${fmtDate(date)}"><strong>${d}</strong><span>${symbol}</span></button>`}).join('')}</div><div class="legend"><span><i></i>Completed</span><span><i class="miss"></i>Missed</span><span><i class="future"></i>Upcoming</span><span>○ Not recorded / earlier</span></div><div class="section-heading"><h2>Week by week</h2></div><div class="settings-card"><div class="week-bars">${[0,1,2,3].map(w=>`<div class="week-bar-wrap"><div class="week-bar" style="height:${Math.max(5,weeklyPercent(c,w))}%;opacity:${weeklyPercent(c,w)?1:.45}"></div><div>Week ${w+1}</div><div class="week-bar-label">${weeklyPercent(c,w)}% complete</div></div>`).join('')}</div><div class="detail-stats" style="grid-template-columns:repeat(3,1fr);margin-top:15px"><div class="detail-stat"><b>${c.measurement?.enabled?avg:'—'}</b><span>${c.measurement?.enabled?'Average '+esc(c.measurement.unit):'No result tracking'}</span></div><div class="detail-stat"><b>${c.measurement?.enabled?high:'—'}</b><span>Highest ${c.measurement?.enabled?esc(c.measurement.unit):'result'}</span></div><div class="detail-stat"><b>${c.measurement?.enabled?low:'—'}</b><span>Lowest ${c.measurement?.enabled?esc(c.measurement.unit):'result'}</span></div></div></div><div class="section-heading"><h2>Current goal</h2></div><div class="goal-box"><span>Days ${day<=7?'1–7':day<=14?'8–14':day<=21?'15–21':'22–30'}</span>${esc(goalFor(c,day)||'No goal set yet.')}</div><div class="section-heading"><h2>Awards</h2></div><div class="award-grid">${awardDefs().filter(d=>c.awards.includes(d[0])).map(d=>`<article class="award-card"><div class="award-icon">${d[1]}</div><div><h3>${d[2]}</h3><p>${d[3]}</p></div></article>`).join('')||'<p class="muted">Your first award is waiting for Day 1.</p>'}</div>${c.status==='completed'?`<div class="empty-state"><img class="empty-mark" src="./assets/logo.svg" alt=""><h2>30 Days Complete!</h2><p>You completed ${completedCount(c)} days with a longest streak of ${st.longest}${c.measurement?.enabled&&vals.length?` and a total of ${vals.reduce((a,b)=>a+b,0)} ${esc(c.measurement.unit)}, averaging ${avg} per day.`:'.'} That’s something to be proud of.</p><div class="button-row"><button class="button" data-action="copy-completion-prompt" data-id="${esc(c.id)}">Copy 30-day graphic prompt</button><button class="button button-quiet" data-action="duplicate" data-id="${esc(c.id)}">Do this challenge again</button></div></div>`:''}`}
  function render(){document.body.classList.add('ready');const route=decodeURIComponent(location.hash.slice(1)||'today').split('/');const page=route[0];document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page));if(page==='challenge'){const c=data.challenges.find(x=>x.id===route[1]);main.innerHTML=c?`<div class="main-inner">${renderDetail(c)}</div>`:`<div class="empty-state"><h2>Challenge not found</h2><a class="button" href="#challenges">Back to challenges</a></div>`}else if(page==='challenges')main.innerHTML=renderChallenges();else if(page==='awards')main.innerHTML=renderAwards();else if(page==='history')main.innerHTML=renderHistory();else if(page==='settings')main.innerHTML=renderSettings();else main.innerHTML=renderTodayView();}
  function modal(title,subtitle,body,footer='',wide=false){modalRoot.innerHTML=`<div class="modal-backdrop" role="presentation"><section class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><div><h2 id="modalTitle">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-close aria-label="Close dialog">×</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;$('.modal-backdrop',modalRoot).addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});$('.modal',modalRoot).addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});setTimeout(()=>$('.modal input:not([type=hidden]),.modal textarea,.modal select,.modal button',modalRoot)?.focus(),20)}
  function closeModal(){modalRoot.innerHTML=''}
  function challengeForm(c=null,duplicate=false){const editing=!!c&&!duplicate;const title=duplicate?c.title:c?.title||'';const start=duplicate?localISO():c?.startDate||localISO();const startingDay=duplicate?1:c?.startingDay||1;const goals=duplicate?{...c.weeklyGoals}:c?.weeklyGoals||{week1:'',week2:'',week3:'',week4:''};const measure=duplicate?{...c.measurement}:c?.measurement||{enabled:false,unit:''};const body=`<form id="challengeForm"><div class="field"><label for="title">Challenge title</label><input id="title" name="title" maxlength="80" required placeholder="30 Days of Push-ups" value="${esc(title)}"></div><div class="field"><label for="description">Description <span class="muted">Optional</span></label><textarea id="description" name="description" maxlength="280" placeholder="What are you hoping to build?">${esc(c?.description||'')}</textarea></div><div class="form-grid"><div class="field"><label for="startDate">Starting date</label><input id="startDate" name="startDate" type="date" required value="${esc(start)}"><small>This is the date for the day number entered here.</small></div><div class="field"><label for="startingDay">What day are you currently on?</label><input id="startingDay" name="startingDay" type="number" min="1" max="30" required value="${startingDay}"><small>For example, enter 12 if today is Day 12. Your earlier days will appear on the calendar.</small></div></div><div id="priorDays" class="field" ${startingDay<=1?'hidden':''}><label>Earlier days</label><div class="previous-choice"><label class="radio-card"><input type="radio" name="prior" value="complete" ${editing?'disabled':''}><span>Mark Days 1–${startingDay-1} complete<small>Count these days as completed.</small></span></label><label class="radio-card"><input type="radio" name="prior" value="unrecorded" checked ${editing?'disabled':''}><span>Leave them unrecorded<small>They won't be counted as missed.</small></span></label></div></div><div class="goal-section"><h3>Weekly goals</h3><p>Set a focus for each week. Copy any earlier goal where it fits.</p>${[['week1','Week 1','Days 1–7',[]],['week2','Week 2','Days 8–14',['Week 1']],['week3','Week 3','Days 15–21',['Week 1','Week 2']],['week4','Final week','Days 22–30',['Week 1','Week 2','Week 3']]].map(([key,label,range,options],i)=>`<div class="goal-line"><label for="${key}">${label}<br><span class="muted">${range}</span></label><input id="${key}" name="${key}" maxlength="120" placeholder="e.g. 20 minutes a day" value="${esc(goals[key]||'')}">${options.length?`<select data-copy-target="${key}" aria-label="Copy goal for ${label}"><option value="">Copy goal from…</option>${options.map((o,j)=>`<option value="${['week1','week2','week3'][j]}">${o}</option>`).join('')}</select>`:'<span></span>'}</div>`).join('')}</div><div class="goal-section"><h3>Track a measurable result</h3><p>Optional. Use this for repetitions, minutes, miles, pages, or another number.</p><div class="field-inline"><input type="checkbox" id="trackResult" name="trackResult" ${measure.enabled?'checked':''}><label for="trackResult" style="margin:0;font-size:12px;font-weight:600">Track a result for each day</label></div><div class="field" id="unitField" style="margin-top:12px" ${measure.enabled?'':'hidden'}><label for="unit">Measurement unit</label><input id="unit" name="unit" maxlength="30" placeholder="e.g. push-ups, minutes, miles" value="${esc(measure.unit||'')}"></div></div><div class="field" style="margin-top:16px"><label class="field-inline" style="font-weight:600"><input type="checkbox" name="notifications" ${!editing||c.reminders!==false?'checked':''}> Include in reminder counts</label><small>You can adjust reminders in Settings.</small></div></form>`;const footer=`<button class="button button-quiet" data-close>Cancel</button><button class="button" id="saveChallenge">${editing?'Save changes':duplicate?'Create a fresh challenge':'Create challenge'}</button>`;modal(editing?'Edit challenge':duplicate?'Do this challenge again':'Start a 30-day challenge',editing?'Update your details and weekly goals.':'Pick something you want to show up for.',body,footer,true);const form=$('#challengeForm');$('#startingDay',form).addEventListener('input',()=>{const d=Math.max(1,Math.min(30,Number($('#startingDay',form).value)||1));$('#priorDays',form).hidden=d<=1;$('.radio-card:first-child span',form).innerHTML=`Mark Days 1–${d-1} complete<small>Count these days as completed.</small>`});$('#trackResult',form).addEventListener('change',()=>$('#unitField',form).hidden=!$('#trackResult',form).checked);form.querySelectorAll('[data-copy-target]').forEach(sel=>sel.addEventListener('change',()=>{if(sel.value)form.elements[sel.dataset.copyTarget].value=form.elements[sel.value].value;sel.value=''}));$('#saveChallenge').onclick=async()=>{if(!form.reportValidity())return;const f=new FormData(form);const day=Number(f.get('startingDay'));const startDate=f.get('startDate');if(day<1||day>30||!startDate){toastMsg('Choose a valid date and a day from 1 to 30.');return}if(editing&&day!==c.startingDay||editing&&startDate!==c.startDate){if(!confirm('Changing the start date or challenge day changes the dates shown on your calendar. Continue?'))return}
      if(editing){Object.assign(c,{title:f.get('title').trim(),description:f.get('description').trim(),startDate,startingDay:day,weeklyGoals:{week1:f.get('week1').trim(),week2:f.get('week2').trim(),week3:f.get('week3').trim(),week4:f.get('week4').trim()},measurement:{enabled:f.has('trackResult'),unit:f.has('trackResult')?f.get('unit').trim():''},reminders:f.has('notifications')});c.updatedAt=new Date().toISOString()}
      else {const nc={id:id(),title:f.get('title').trim(),description:f.get('description').trim(),startDate,startingDay:day,status:'active',measurement:{enabled:f.has('trackResult'),unit:f.has('trackResult')?f.get('unit').trim():''},weeklyGoals:{week1:f.get('week1').trim(),week2:f.get('week2').trim(),week3:f.get('week3').trim(),week4:f.get('week4').trim()},days:[],awards:[],reminders:f.has('notifications'),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};if(day>1&&f.get('prior')==='complete'){for(let n=1;n<day;n++){const dt=shiftDate(startDate,n-day);nc.days.push({day:n,date:dt,completed:true,completedAt:new Date().toISOString(),notes:'',value:null})}}data.challenges.unshift(nc);c=nc}
      await save();const earned=refreshAwards(c);await save();closeModal();location.hash=`#challenge/${encodeURIComponent(c.id)}`;render();if(earned.length)showAward(earned[0]);else toastMsg(editing?'Challenge updated.':'Challenge started. You’ve got this.');};}
  function dailyDialog(c,day=currentDay(c)){day=Math.max(1,Math.min(30,Number(day)||1));const date=challengeDates(c)[day-1],rec=dayRecord(c,day)||{},state=dayState(c,day),isFuture=date>localISO();const statusOptions=isFuture?[['not','Not yet reached'],['completed','Completed early'],['skipped','Skipped']]:[['not','Not completed'],['completed','Completed'],['skipped','Skipped']];const initial=rec.completed?'completed':rec.skipped?'skipped':'not';const body=`<form id="dayForm"><div class="notice">Day ${day} · ${fmtDate(date)}${date===localISO()?' · Today':''}<br>${esc(goalFor(c,day)||'No goal set for this week.')}</div><div class="field"><label for="dayStatus">Status</label><select id="dayStatus" name="status">${statusOptions.map(([v,l])=>`<option value="${v}" ${initial===v?'selected':''}>${l}</option>`).join('')}</select></div>${c.measurement?.enabled?`<div class="field"><label for="value">Result (${esc(c.measurement.unit)}) <span class="muted">Optional</span></label><input id="value" name="value" type="number" min="0" step="any" value="${rec.value??''}" placeholder="Add your result"></div>`:''}<div class="field"><label for="notes">Notes <span class="muted">Optional</span></label><textarea id="notes" name="notes" maxlength="1200" placeholder="What went well today?">${esc(rec.notes||'')}</textarea></div>${rec.completed?`<button type="button" class="button button-quiet" data-action="copy-day-prompt" data-id="${esc(c.id)}" data-day="${day}">Copy graphic prompt</button>`:''}</form>`;modal(`Day ${day}`,`Your ${esc(c.title)} check-in`,body,`<button class="button button-quiet" data-close>Cancel</button><button class="button" id="saveDay">Save day</button>`);$('#saveDay').onclick=async()=>{const form=$('#dayForm'),f=new FormData(form),before=JSON.stringify(c.days),beforeAwards=[...c.awards],beforeAwardLog=[...(c.awardLog||[])],beforeStatus=c.status,beforeFinished=c.finishedAt,status=f.get('status');let target=dayRecord(c,day);if(!target){target={day,date,completed:false,notes:'',value:null};c.days.push(target)}target.date=date;target.completed=status==='completed';target.skipped=status==='skipped';target.completedAt=target.completed?(target.completedAt||new Date().toISOString()):null;target.notes=f.get('notes').trim();if(c.measurement?.enabled)target.value=f.get('value')===''?null:Number(f.get('value'));if(!target.completed&&!target.skipped&&!target.notes&&!target.value)c.days=c.days.filter(x=>x!==target);const earned=refreshAwards(c,day);updateCompletion(c);await save();closeModal();render();const reverted=()=>{c.days=JSON.parse(before);c.awards=beforeAwards;c.awardLog=beforeAwardLog;c.status=beforeStatus;c.finishedAt=beforeFinished;save().then(render)};if(status==='completed'&&!JSON.parse(before).find(x=>x.day===day)?.completed){const final=c.status==='completed';toastMsg(final?'30 Days Complete!':`Day ${day} complete. Keep it going.`,reverted,{label:final?'Copy final graphic prompt':'Copy graphic prompt',onClick:()=>copyGraphicPrompt(final?completionGraphicPrompt(c):dayGraphicPrompt(c,day))})}else toastMsg('Day saved.');if(earned.length)showAward(earned[0]);if(c.status==='completed')render()}}
  function showAward(a){const n=document.createElement('div');n.className='award-pop';n.innerHTML=`<div class="award-pop-inner"><span>${a.icon}</span><h3>${esc(a.name)}</h3><p>A new award is yours.</p></div>`;document.body.append(n);setTimeout(()=>n.remove(),2800)}
  function duplicateChallenge(c){challengeForm(c,true)}
  async function toggleStatus(c){const before=c.status;if(before==='active'){c.status='paused';c.pausedAt=localISO()}else if(before==='paused'){const daysPaused=Math.max(0,dateDiff(c.pausedAt||localISO(),localISO()));if(daysPaused){c.startDate=shiftDate(c.startDate,daysPaused);for(const d of c.days)if(d.date>=(c.pausedAt||localISO()))d.date=shiftDate(d.date,daysPaused)}c.pausedAt=null;c.status='active'}else if(before==='archived')c.status=c.previousStatus||'active';else if(before==='completed'){c.previousStatus='completed';c.status='archived';c.archivedAt=localISO()}c.updatedAt=new Date().toISOString();await save();render();toastMsg(c.status==='paused'?'Challenge paused. Its calendar is on hold.':c.status==='active'?'Challenge resumed.':'Challenge archived.')}
  function confirmDelete(c){modal(`Delete “${esc(c.title)}”?`,'This permanently removes the challenge and all its history. This cannot be undone.','<p class="notice">Your other challenges and settings will stay as they are.</p>',`<button class="button button-quiet" data-close>Cancel</button><button class="button button-danger" id="confirmDelete">Delete challenge</button>`);$('#confirmDelete').onclick=async()=>{data.challenges=data.challenges.filter(x=>x.id!==c.id);await save();closeModal();location.hash='#challenges';render();toastMsg('Challenge deleted.')}}
  function confirmReset(){modal('Reset app data?','This will remove every challenge and setting stored on this device.','<p class="notice">Export a backup first if you want to keep your progress.</p>',`<button class="button button-quiet" data-close>Cancel</button><button class="button button-danger" id="doReset">Reset everything</button>`);$('#doReset').onclick=async()=>{data={challenges:[],settings:{theme:'system',notifications:false,dailyReminder:false,dailyTime:'07:00',incompleteReminder:false,incompleteTime:'20:00'}};await save();closeModal();location.hash='#today';render();toastMsg('App data reset.')}}
  function exportData(){const blob=new Blob([JSON.stringify({app:'30 Days of…',version:VERSION,exportedAt:new Date().toISOString(),...data},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`30-days-of-backup-${localISO()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toastMsg('Backup downloaded.')}
  function validateBackup(x){if(!x||!Array.isArray(x.challenges)||!x.settings||typeof x.settings!=='object')throw Error('This file is not a 30 Days of… backup.');for(const c of x.challenges){if(!c||typeof c.id!=='string'||typeof c.title!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(c.startDate)||!Number.isInteger(Number(c.startingDay))||c.startingDay<1||c.startingDay>30||!Array.isArray(c.days))throw Error('The backup contains an invalid challenge.');for(const d of c.days)if(!Number.isInteger(Number(d.day))||d.day<1||d.day>30||typeof d.completed!=='boolean')throw Error('The backup contains an invalid daily record.')}return normalize(x)}
  function importData(){const body=`<p class="notice">Choose a 30 Days of… JSON backup. You can replace current data or merge it with what is already here.</p><div class="field"><label class="radio-card"><input type="radio" name="importMode" value="merge" checked><span>Merge with current data<small>Matching challenge IDs use the imported version.</small></span></label><label class="radio-card"><input type="radio" name="importMode" value="replace"><span>Replace current data<small>Everything here will be overwritten.</small></span></label></div><input id="backupFile" type="file" accept="application/json,.json">`;modal('Import backup','Validate your backup before loading it.',body,`<button class="button button-quiet" data-close>Cancel</button><button class="button" id="loadBackup">Choose and import</button>`);$('#loadBackup').onclick=()=>$('#backupFile').click();$('#backupFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const parsed=validateBackup(JSON.parse(await file.text()));const mode=$('input[name=importMode]:checked').value;if(mode==='replace'){if(!confirm('Replace all current data with this backup?'))return;data=parsed}else{const map=new Map(data.challenges.map(c=>[c.id,c]));parsed.challenges.forEach(c=>map.set(c.id,c));data.challenges=Array.from(map.values());data.settings={...data.settings,...parsed.settings}}await save();applyTheme();closeModal();render();toastMsg(mode==='replace'?'Backup restored.':'Backup merged.')}catch(err){toastMsg(err.message.includes('backup')?err.message:'This file could not be read as a valid backup.')}}}
  async function requestNotifications(){if(!('Notification'in window)){toastMsg('Notifications are not available in this browser.');return false}try{const result=await Notification.requestPermission();if(result==='granted'){data.settings.notifications=true;await save();render();toastMsg('Notifications enabled on this device.');return true}toastMsg(result==='denied'?'Permission denied. You can change this in browser settings.':'Notification permission was not granted.');return false}catch{toastMsg('Could not request notification permission.');return false}}
  function notify(title,body,key){if(!('Notification'in window)||Notification.permission!=='granted')return;try{new Notification(title,{body,icon:'./assets/icon-192.png',tag:key})}catch{}}
  function checkReminders(){if(!data.settings.notifications||!('Notification'in window)||Notification.permission!=='granted')return;const now=new Date(),today=localISO(),hm=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;if(data.settings.dailyReminder&&hm>=data.settings.dailyTime&&data.settings.lastDaily!==today){const count=data.challenges.filter(c=>c.status==='active'&&c.reminders!==false&&challengeDates(c)[currentDay(c)-1]===today).length;if(count){notify('Your 30 Days of… challenge is ready',`You have ${count} ${count===1?'challenge':'challenges'} scheduled for today.`,`daily-${today}`);data.settings.lastDaily=today;save()}}if(data.settings.incompleteReminder&&hm>=data.settings.incompleteTime&&data.settings.lastIncomplete!==today){const count=todayNeeds().filter(c=>c.reminders!==false).length;if(count){notify("Don't lose your streak",`You still have ${count} ${count===1?'challenge':'challenges'} to complete today.`,`incomplete-${today}`);data.settings.lastIncomplete=today;save()}}}
  function installHelp(){modal('Install 30 Days of…','Add the app to your device for quick access and offline use.','<div class="notice"><b>iPhone or iPad</b><br>Open this page in Safari, tap Share, then choose “Add to Home Screen.”</div><div class="notice"><b>Android</b><br>Open in Chrome and tap “Install app” or use the browser menu and choose “Install app” / “Add to Home screen.”</div><div class="notice"><b>Mac or desktop</b><br>In a supported browser, choose the install icon near the address bar or use the browser menu.</div>',`<button class="button" data-close>Got it</button>`)}

  document.addEventListener('click',async e=>{const close=e.target.closest('[data-close]');if(close){closeModal();return}const ex=e.target.closest('[data-example]');if(ex){challengeForm();$('#title').value=`30 Days of ${ex.dataset.example}`;return}const filter=e.target.closest('[data-filter]');if(filter){currentFilter=filter.dataset.filter;render();return}const action=e.target.closest('[data-action]');if(!action)return;const c=data.challenges.find(x=>x.id===action.dataset.id);switch(action.dataset.action){case'new':challengeForm();break;case'complete-today':case'edit-today':case'daily':if(c)dailyDialog(c,action.dataset.day||currentDay(c));break;case'copy-day-prompt':if(c)copyGraphicPrompt(dayGraphicPrompt(c,Number(action.dataset.day)||currentDay(c)));break;case'copy-completion-prompt':if(c)copyGraphicPrompt(completionGraphicPrompt(c),'30-day prompt copied. Paste it into ChatGPT.');break;case'edit-challenge':if(c)challengeForm(c);break;case'duplicate':if(c)duplicateChallenge(c);break;case'status':if(c)toggleStatus(c);break;case'delete':if(c){modal('Challenge options',c.title,'<p class="notice">Archive this challenge to keep it in History, or permanently remove all of its history.</p>',`<button class="button button-quiet" data-close>Cancel</button><button class="button button-quiet" id="archiveFromOptions">${c.status==='archived'?'Restore':'Archive'}</button><button class="button button-danger" id="deleteFromOptions">Delete challenge</button>`);$('#deleteFromOptions').onclick=()=>confirmDelete(c);$('#archiveFromOptions').onclick=async()=>{if(c.status==='archived'){c.status=c.previousStatus||'active';c.archivedAt=null}else{c.previousStatus=c.status;c.status='archived';c.archivedAt=localISO()}await save();closeModal();render();toastMsg(c.status==='archived'?'Challenge archived.':'Challenge restored.') }}break;case'export':exportData();break;case'import':importData();break;case'reset':confirmReset();break;case'permission':requestNotifications();break;case'install':installHelp();break;}}
  );
  document.addEventListener('input',e=>{if(e.target.id==='search'){searchTerm=e.target.value;const pos=e.target.selectionStart;render();const next=$('#search');next?.focus();next?.setSelectionRange(pos,pos)}});
  document.addEventListener('change',async e=>{const setting=e.target.dataset.setting;if(!setting)return;const val=e.target.type==='checkbox'?e.target.checked:e.target.value;if(setting==='notifications'&&val){const ok=await requestNotifications();if(!ok){data.settings.notifications=false;render();return}}else{data.settings[setting]=val;await save();if(setting==='theme')applyTheme();render()}});
  window.addEventListener('hashchange',render);
  const isInstalledDisplay=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
  $('#installBtn').hidden=isInstalledDisplay();
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;$('#installBtn').hidden=false});
  window.addEventListener('appinstalled',()=>{deferredInstall=null;$('#installBtn').hidden=true;toastMsg('30 Days of… is installed.')});
  $('#installBtn').addEventListener('click',async()=>{if(deferredInstall){const installPrompt=deferredInstall;deferredInstall=null;await installPrompt.prompt();const result=await installPrompt.userChoice;if(result.outcome==='accepted')$('#installBtn').hidden=true;else if(!isInstalledDisplay())$('#installBtn').hidden=false}else installHelp()});
  $('#quickAdd').addEventListener('click',()=>challengeForm());
  $('#updateNow').addEventListener('click',()=>window.__swWaiting?.postMessage({type:'SKIP_WAITING'}));$('#dismissUpdate').addEventListener('click',()=>$('#updateBanner').hidden=true);
  document.addEventListener('visibilitychange',checkReminders);setInterval(checkReminders,30000);
  async function init(){await load();const newlyEarned=[];for(const c of data.challenges)if(c.status==='active')newlyEarned.push(...refreshAwards(c));if(newlyEarned.length)await save();render();if(newlyEarned.length)showAward(newlyEarned[0]);if('serviceWorker'in navigator){try{const reg=await navigator.serviceWorker.register('./sw.js',{scope:'./'});const showWaitingUpdate=worker=>{if(worker&&reg.waiting===worker&&navigator.serviceWorker.controller){window.__swWaiting=worker;$('#updateBanner').hidden=false}};if(reg.waiting&&navigator.serviceWorker.controller)showWaitingUpdate(reg.waiting);reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){window.__swWaiting=worker;$('#updateBanner').hidden=false}})});navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});reg.update()}catch(e){console.info('Service worker unavailable',e)}}}
  init();
})();
